  private emptyHomePage(): HomePageDraft { return { seoTitle: 'Master Hızlı Okuma | Hız ve Anlamayı Birlikte Geliştirin', seoDescription: 'Başlangıç düzeyinizi ölçün, size uygun çalışmaları takip edin ve gelişiminizi hız ile anlama verileriyle görün.', seoKeywords: 'hızlı okuma, okuduğunu anlama, okuma egzersizleri, kişisel öğrenme planı', seoOgImage: '', heroTitle: 'Hız ve anlamayı birlikte geliştirin', heroSubtitle: 'Başlangıç ölçümünüzden sonra size uygun çalışmalarla ilerleyin; gelişiminizi düzenli verilerle görün.', primaryActionLabel: 'Seviyeni belirle', secondaryActionLabel: 'Nasıl çalışır?', featuresTitle: 'Çalışma akışında neler var?', featuresSubtitle: 'Odak, akıcılık ve anlama çalışmalarını aynı öğrenme yolunda birleştirin.', approachTitle: 'Ölçerek ilerleyen bir çalışma düzeni', approachSubtitle: 'Program, tek bir hız hedefine değil, sürdürülebilir gelişime odaklanır.', pricingTitle: 'Size uygun erişimi seçin', pricingSubtitle: 'Bireysel veya kurumsal erişim seçeneklerini inceleyin.', blogTitle: 'Kaynaklar ve çalışma ipuçları', blogSubtitle: 'Okuma, öğrenme ve düzenli çalışma üzerine içerikleri keşfedin.', newsletterTitle: 'Çalışma ipuçları e-postanıza gelsin', newsletterSubtitle: 'Yeni içeriklerden ve yararlı çalışma önerilerinden haberdar olun.', faqTitle: 'Sık sorulan sorular', faqSubtitle: 'Platform ve çalışma düzeni hakkında kısa yanıtlar.', ctaTitle: 'Çalışma yolunuzu görmek ister misiniz?', ctaSubtitle: 'Seviyenizi belirleyip size uygun ilk adımı görün.', ctaActionLabel: 'Başla', ctaSmallText: 'Sonuçlar başlangıç düzeyine ve düzenli çalışmaya göre değişir.', featuresVisible: true, approachVisible: true, statsVisible: true, pricingVisible: true, blogVisible: true, newsletterVisible: true, faqVisible: true, ctaVisible: true }; }
  private emptyHomeCardsJson(): string { return JSON.stringify({ trustPoints: ['Başlangıç ölçümü', 'Hız ve anlama birlikte', 'Kişisel çalışma akışı'], features: [{ icon: 'speed', title: 'Akıcılık çalışmaları', description: 'Metin takibi ve kelime gruplama ile daha akıcı okuyun.' }, { icon: 'quiz', title: 'Anlama kontrolü', description: 'Her çalışmada anlama sonucunu ayrı olarak görün.' }, { icon: 'route', title: 'Kişisel sıradaki adım', description: 'Ölçüm geçmişinize göre uygun içerikle devam edin.' }, { icon: 'insights', title: 'İlerleme görünümü', description: 'Hız, anlama ve düzenli çalışma eğilimini izleyin.' }], approach: [{ title: 'Başlangıcı görün', role: 'Ölçüm', description: 'Çalışma yolunuz başlangıç ölçümünüzle netleşir.' }, { title: 'Dengeli ilerleyin', role: 'Hız + anlama', description: 'Zorluk, sonuçlarınıza göre dengelenir.' }, { title: 'Geri bildirimi kullanın', role: 'İzleme', description: 'Güçlü yönlerinizi ve destek ihtiyacını görün.' }], benefits: ['Yeni çalışma önerileri', 'Güncel içerikler', 'İstediğiniz zaman abonelikten çıkma özgürlüğü'] }, null, 2); }
  private loadHomePageDraft(raw?: string): void { const defaults = this.emptyHomePage(); this.homePageCardsJson = this.emptyHomeCardsJson(); if (!raw) { this.homePageDraft = defaults; return; } try { const config = JSON.parse(raw) as Record<string, any>; const section = (name: string) => config[name] && typeof config[name] === 'object' ? config[name] : {}; const seo = section('seo'); const hero = section('hero'); const features = section('features'); const approach = section('approach'); const pricing = section('pricing'); const blog = section('blog'); const newsletter = section('newsletter'); const faq = section('faq'); const cta = section('cta'); const visibility = section('visibility'); this.homePageDraft = { ...defaults, seoTitle: seo.title || defaults.seoTitle, seoDescription: seo.description || defaults.seoDescription, seoKeywords: seo.keywords || defaults.seoKeywords, seoOgImage: seo.ogImage || '', heroTitle: hero.title || defaults.heroTitle, heroSubtitle: hero.subtitle || defaults.heroSubtitle, primaryActionLabel: hero.primaryActionLabel || defaults.primaryActionLabel, secondaryActionLabel: hero.secondaryActionLabel || defaults.secondaryActionLabel, featuresTitle: features.title || defaults.featuresTitle, featuresSubtitle: features.subtitle || defaults.featuresSubtitle, approachTitle: approach.title || defaults.approachTitle, approachSubtitle: approach.subtitle || defaults.approachSubtitle, pricingTitle: pricing.title || defaults.pricingTitle, pricingSubtitle: pricing.subtitle || defaults.pricingSubtitle, blogTitle: blog.title || defaults.blogTitle, blogSubtitle: blog.subtitle || defaults.blogSubtitle, newsletterTitle: newsletter.title || defaults.newsletterTitle, newsletterSubtitle: newsletter.subtitle || defaults.newsletterSubtitle, faqTitle: faq.title || defaults.faqTitle, faqSubtitle: faq.subtitle || defaults.faqSubtitle, ctaTitle: cta.title || defaults.ctaTitle, ctaSubtitle: cta.subtitle || defaults.ctaSubtitle, ctaActionLabel: cta.actionLabel || defaults.ctaActionLabel, ctaSmallText: cta.smallText || defaults.ctaSmallText, featuresVisible: typeof visibility.features === 'boolean' ? visibility.features : defaults.featuresVisible, approachVisible: typeof visibility.approach === 'boolean' ? visibility.approach : defaults.approachVisible, statsVisible: typeof visibility.stats === 'boolean' ? visibility.stats : defaults.statsVisible, pricingVisible: typeof visibility.pricing === 'boolean' ? visibility.pricing : defaults.pricingVisible, blogVisible: typeof visibility.blog === 'boolean' ? visibility.blog : defaults.blogVisible, newsletterVisible: typeof visibility.newsletter === 'boolean' ? visibility.newsletter : defaults.newsletterVisible, faqVisible: typeof visibility.faq === 'boolean' ? visibility.faq : defaults.faqVisible, ctaVisible: typeof visibility.cta === 'boolean' ? visibility.cta : defaults.ctaVisible }; this.homePageCardsJson = JSON.stringify({ trustPoints: Array.isArray(hero.trustPoints) ? hero.trustPoints : JSON.parse(this.emptyHomeCardsJson()).trustPoints, features: Array.isArray(features.items) ? features.items : JSON.parse(this.emptyHomeCardsJson()).features, approach: Array.isArray(approach.items) ? approach.items : JSON.parse(this.emptyHomeCardsJson()).approach, benefits: Array.isArray(newsletter.benefits) ? newsletter.benefits : JSON.parse(this.emptyHomeCardsJson()).benefits }, null, 2); } catch { this.homePageDraft = defaults; this.error.set('Ana sayfa kaydı okunamadı; güvenli varsayılanlar yüklendi.'); } }
  private emptyBlock(): SpeedReadingCmsContentBlockRequest { return { key: '', group: 'HomePage', label: null, type: 0, value: '' }; }
  private emptyEvidenceMetric(): EvidenceMetricDraft { return { title: '', value: '', description: '', source: '', period: '', sampleSize: null, icon: 'insights', isVisible: false }; }
  private toEvidenceMetric(block: SpeedReadingCmsContentBlock): EvidenceMetric | null {
    try {
      const value = JSON.parse(block.value) as Partial<EvidenceMetricDraft>;
      if (!block.label?.trim() || typeof value.value !== 'string' || typeof value.source !== 'string' || typeof value.period !== 'string' || typeof value.sampleSize !== 'number' || value.sampleSize < 1) return null;
      return {
        id: block.id,
        key: block.key,
        title: block.label,
        value: value.value,
        description: typeof value.description === 'string' ? value.description : '',
        source: value.source,
        period: value.period,
        sampleSize: value.sampleSize,
        icon: evidenceMetricIcons.includes(value.icon ?? '') ? value.icon! : 'insights',
        isVisible: value.isVisible === true
      };
    } catch {
      return null;
    }
  }
  private emptyPage(): SpeedReadingCmsPageRequest { return { title: '', slug: '', content: '', isPublished: false, scheduledPublishAt: null, seoSettings: this.emptySeo() }; }
  private emptyBlog(): SpeedReadingCmsBlogPostRequest { return { title: '', slug: '', summary: null, content: '', author: null, publishedAt: null, scheduledPublishAt: null, tags: [], coverImageUrl: null, isPublished: false, seoSettings: this.emptySeo() }; }
